-- Bộ lọc thông số + nhu cầu của catalogue (2026-10-30), xuất từ DB sau khi nạp 03 → 05.
--   product_filter_values: kết quả POST /api/v1/admin/products/reindex-filters (FilterNormalizer đọc thông số);
--     sửa thông số / thêm sản phẩm thì gọi lại API đó, file này chỉ để volume mới có sẵn bộ lọc.
--   needs / product_needs: nhu cầu cào từ TGDĐ (Raw_data/import_needs.py, crawl_v5/needs.json).
--   Sản phẩm khớp theo products.sku (không theo id); sản phẩm không có thì bỏ qua.
-- Docker chạy file này sau 05 khi tạo volume mới. Chạy lại nhiều lần vẫn an toàn (trùng thì bỏ qua):
--   docker exec -i techshopping-postgres psql -U postgres -d techshopping < database/docker-init/08_catalog_filters_needs.sql

begin;

do $$
begin
    if current_database() <> 'techshopping' then
        raise exception 'Chỉ nạp bộ lọc / nhu cầu vào database techshopping.';
    end if;
end $$;

insert into needs (category_id, slug, name, display_order)
select c.category_id, v.slug, v.name, v.display_order
from (values
    ('dien-thoai', 'choi-game', 'Chơi game / Cấu hình cao', 1),
    ('dien-thoai', 'chup-anh-quay-phim', 'Chụp ảnh, quay phim', 2),
    ('dien-thoai', 'pin-khung', 'Pin khủng', 3),
    ('dien-thoai', 'livestream', 'Livestream', 4),
    ('dien-thoai', 'mong-nhe', 'Mỏng nhẹ', 5),
    ('dien-thoai', 'pho-thong', 'Phổ thông', 6),
    ('laptop', 'gaming', 'Gaming', 1),
    ('laptop', 'hoc-tap-van-phong', 'Học tập, văn phòng', 2),
    ('laptop', 'do-hoa', 'Đồ hoạ', 3),
    ('laptop', 'mong-nhe', 'Mỏng nhẹ', 4),
    ('laptop', 'cao-cap', 'Cao cấp', 5),
    ('may-tinh-bang', 'choi-game', 'Chơi game / Cấu hình cao', 1),
    ('may-tinh-bang', 'tre-em', 'Cho trẻ em', 2)
) v(category_slug, slug, name, display_order)
join categories c on c.slug = v.category_slug
on conflict (category_id, slug) do nothing;

